<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$control=[];$customer=[];$supplier=[];$m=['customer_receivable'=>0.0,'customer_credit'=>0.0,'supplier_payable'=>0.0,'overdue'=>0.0];
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);sales_step15_backfill($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$control=finance_step16_control_balances($pdo,$orgId);$stmt=$pdo->prepare("SELECT f.order_id,f.receivable_amount,f.customer_credit_due,f.effective_charge,f.net_collected,o.order_date,COALESCE(c.customer_name,cl.customer_name_snapshot,q.customer_name,'Unlinked customer') customer_name FROM sales_fulfillment_ledger f JOIN orders o ON o.id=f.order_id AND o.organization_id=f.organization_id LEFT JOIN sales_customer_links cl ON cl.order_id=f.order_id AND cl.organization_id=f.organization_id LEFT JOIN crm_customers c ON c.id=cl.customer_id AND c.organization_id=f.organization_id LEFT JOIN product_quote_order_links ql ON ql.order_id=f.order_id AND ql.organization_id=f.organization_id LEFT JOIN product_quotes q ON q.id=ql.quote_id AND q.organization_id=f.organization_id JOIN product_sale_ledger sl ON sl.order_id=f.order_id AND sl.organization_id=f.organization_id WHERE f.organization_id=? AND sl.sale_status='active' AND (f.receivable_amount>0.009 OR f.customer_credit_due>0.009) ORDER BY o.order_date DESC,f.order_id DESC");$stmt->execute([$orgId]);$customer=$stmt->fetchAll();foreach($customer as $r){$m['customer_receivable']+=(float)$r['receivable_amount'];$m['customer_credit']+=(float)$r['customer_credit_due'];}$supplier=purchase_step14_bill_rows($pdo,$orgId,'active');foreach($supplier as &$r){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$r['id']);$r['outstanding']=$st['outstanding'];$m['supplier_payable']+=$st['outstanding'];if($st['outstanding']>0.009&&$r['due_date']&&$r['due_date']<date('Y-m-d'))$m['overdue']+=$st['outstanding'];}unset($r);}catch(Throwable $e){$error=$e->getMessage();}
function rp_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function rp_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Receivable Payable - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Receivable / Payable</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_receivables.php">Customer Ledger</a><a class="os-btn" href="supplier_payments.php">Supplier Payables</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a class="active" href="finance_receivable_payable.php"><i class="dot"></i>AR / AP</a><a href="finance_journal.php"><i class="dot"></i>Journal Ledger</a><a href="finance_reconciliation.php"><i class="dot"></i>Bank Reconciliation</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 16G • CONTROL ACCOUNT RECONCILIATION</div><h1>Compare customer and supplier operational balances with the general ledger.</h1><p>Operational receivable/payable remains the detailed sub-ledger; STEP 16 Accounts Receivable and Accounts Payable are the GL control accounts.</p></section><?php if($error):?><div class="pp-alert bad"><strong>AR/AP diagnostic:</strong> <?= rp_h($error) ?></div><?php else:?><section class="s10-kpis"><div class="s10-kpi"><small>Customer Receivable</small><strong><?= rp_m($m['customer_receivable']) ?></strong><span>STEP 15 sub-ledger</span></div><div class="s10-kpi"><small>GL Accounts Receivable</small><strong><?= rp_m($control['accounts_receivable']??0) ?></strong><span>Difference <?= rp_m(($control['accounts_receivable']??0)-$m['customer_receivable']+$m['customer_credit']) ?></span></div><div class="s10-kpi"><small>Supplier Payable</small><strong><?= rp_m($m['supplier_payable']) ?></strong><span><?= rp_m($m['overdue']) ?> overdue</span></div><div class="s10-kpi"><small>GL Accounts Payable</small><strong><?= rp_m($control['accounts_payable']??0) ?></strong><span>Difference <?= rp_m(($control['accounts_payable']??0)-$m['supplier_payable']) ?></span></div></section><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-6"><h2>Customer Receivables / Credits</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Sale</th><th>Customer</th><th>Charge</th><th>Collected</th><th>Receivable</th><th>Credit Due</th></tr></thead><tbody><?php foreach($customer as $r):?><tr><td>#<?= (int)$r['order_id'] ?><small><?= rp_h($r['order_date']) ?></small></td><td><?= rp_h($r['customer_name']) ?></td><td><?= rp_m($r['effective_charge']) ?></td><td><?= rp_m($r['net_collected']) ?></td><td><b><?= rp_m($r['receivable_amount']) ?></b></td><td><?= rp_m($r['customer_credit_due']) ?></td></tr><?php endforeach;?><?php if(!$customer):?><tr><td colspan="6">No customer receivable or credit balance.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-6"><h2>Supplier Payables</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Invoice</th><th>Supplier</th><th>Due</th><th>Total</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody><?php foreach($supplier as $r):?><?php if((float)$r['outstanding']<=0.009)continue;?><tr><td><?= rp_h($r['invoice_number']) ?><small><?= rp_h($r['invoice_date']) ?></small></td><td><?= rp_h($r['supplier_name']) ?></td><td><?= rp_h($r['due_date']?:'—') ?></td><td><?= rp_m($r['total_amount']) ?></td><td><?= rp_m($r['paid_amount']) ?></td><td><b><?= rp_m($r['outstanding']) ?></b></td></tr><?php endforeach;?><?php if($m['supplier_payable']<=0.009):?><tr><td colspan="6">No supplier payable outstanding.</td></tr><?php endif;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Control rule:</strong> Customer credit balances can make the AR control lower than gross operational receivables; this is shown explicitly rather than hidden.</div><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
